package cn.jingyu.deepseek;

import org.json.*;import java.io.*;import java.util.*;import java.util.regex.*;import java.util.zip.*;

/** Deterministic A4 document templates: real styles, lists, tables, links and editable math. */
public final class DocxWriter {
 private static final String NS="http://schemas.openxmlformats.org/wordprocessingml/2006/main";
 private final DocumentLayout layout;private final StringBuilder listOverrides=new StringBuilder();private int listId=2;private final JSONObject spec;private final String accent;private final StringBuilder links=new StringBuilder();private int linkNumber;
 private DocxWriter(JSONObject s)throws Exception{spec=s;layout=new DocumentLayout(s);accent=layout.accent;}
 public static void write(OutputStream output,JSONObject spec)throws Exception {new DocxWriter(spec).write(output);}
 private void write(OutputStream out)throws Exception {String content=ArtifactFiles.withSources(spec).replace("\r\n","\n");String title=ArtifactSkills.title(spec);String body=body(content);
  try(ZipOutputStream z=new ZipOutputStream(out)){
   ArtifactFiles.entry(z,"[Content_Types].xml",ArtifactFiles.types(ArtifactFiles.override("word/document.xml","wordprocessingml.document.main")+ArtifactFiles.override("word/styles.xml","wordprocessingml.styles")+ArtifactFiles.override("word/numbering.xml","wordprocessingml.numbering")+(layout.numbers?ArtifactFiles.override("word/footer1.xml","wordprocessingml.footer"):"")));
   ArtifactFiles.entry(z,"_rels/.rels",ArtifactFiles.rels(ArtifactFiles.rel("rId1","officeDocument","word/document.xml")));
   ArtifactFiles.entry(z,"word/_rels/document.xml.rels",ArtifactFiles.rels(ArtifactFiles.rel("rId1","styles","styles.xml")+ArtifactFiles.rel("rId2","numbering","numbering.xml")+(layout.numbers?ArtifactFiles.rel("rId3","footer","footer1.xml"):"")+links));
   if(layout.numbers)ArtifactFiles.entry(z,"word/footer1.xml",ArtifactFiles.HEADER+"<w:ftr xmlns:w=\""+NS+"\"><w:p><w:pPr><w:jc w:val=\"center\"/></w:pPr><w:fldSimple w:instr=\"PAGE\"><w:r><w:rPr><w:sz w:val=\"18\"/><w:color w:val=\"687780\"/></w:rPr><w:t>1</w:t></w:r></w:fldSimple></w:p></w:ftr>");ArtifactFiles.entry(z,"word/styles.xml",styles());ArtifactFiles.entry(z,"word/numbering.xml",numbering());
   ArtifactFiles.entry(z,"word/document.xml",ArtifactFiles.HEADER+"<w:document xmlns:w=\""+NS+"\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\" xmlns:m=\"http://schemas.openxmlformats.org/officeDocument/2006/math\"><w:body>"+body+"<w:sectPr>"+(layout.numbers?"<w:footerReference w:type=\"default\" r:id=\"rId3\"/>":"")+"<w:pgSz w:w=\""+(layout.landscape?16838:11906)+"\" w:h=\""+(layout.landscape?11906:16838)+"\""+(layout.landscape?" w:orient=\"landscape\"":"")+"/><w:pgMar w:top=\"1300\" w:right=\"1440\" w:bottom=\"1300\" w:left=\"1440\" w:header=\"600\" w:footer=\"600\"/></w:sectPr></w:body></w:document>");
  }
 }
 private String styles(){String font=ArtifactSkills.style(spec).equals("formal")?"宋体":"等线";StringBuilder s=new StringBuilder(ArtifactFiles.HEADER+"<w:styles xmlns:w=\""+NS+"\"><w:docDefaults><w:rPrDefault><w:rPr><w:rFonts w:ascii=\"Calibri\" w:hAnsi=\"Calibri\" w:eastAsia=\""+font+"\"/><w:color w:val=\"24342F\"/><w:sz w:val=\""+Math.round(layout.font*2)+"\"/><w:lang w:val=\"en-US\" w:eastAsia=\"zh-CN\"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after=\"140\" w:line=\"340\" w:lineRule=\"auto\"/><w:widowControl/></w:pPr></w:pPrDefault></w:docDefaults><w:style w:type=\"paragraph\" w:default=\"1\" w:styleId=\"Normal\"><w:name w:val=\"Normal\"/></w:style>");
  String[] names={"Title","Heading1","Heading2","Heading3"};int[] sizes={46,30,25,23};for(int i=0;i<4;i++)s.append("<w:style w:type=\"paragraph\" w:styleId=\"").append(names[i]).append("\"><w:name w:val=\"").append(i==0?"Title":"heading "+i).append("\"/><w:basedOn w:val=\"Normal\"/><w:next w:val=\"Normal\"/><w:pPr><w:keepNext/><w:keepLines/><w:spacing w:before=\"").append(i==0?0:300).append("\" w:after=\"").append(i==0?340:140).append("\"/>").append(i>0?"<w:outlineLvl w:val=\""+(i-1)+"\"/>":"").append("</w:pPr><w:rPr><w:b/><w:color w:val=\"").append(i==0?"17272E":accent).append("\"/><w:sz w:val=\"").append(sizes[i]).append("\"/></w:rPr></w:style>");return s+"</w:styles>";
 }
 private String numbering(){StringBuilder b=new StringBuilder(ArtifactFiles.HEADER+"<w:numbering xmlns:w=\""+NS+"\">");for(int type=0;type<2;type++){b.append("<w:abstractNum w:abstractNumId=\"").append(type).append("\"><w:multiLevelType w:val=\"multilevel\"/>");for(int level=0;level<4;level++)b.append("<w:lvl w:ilvl=\"").append(level).append("\"><w:start w:val=\"1\"/><w:numFmt w:val=\"").append(type==0?"bullet":"decimal").append("\"/><w:lvlText w:val=\"").append(type==0?"•":"%"+(level+1)+".").append("\"/><w:pPr><w:ind w:left=\"").append(420*(level+1)).append("\" w:hanging=\"260\"/></w:pPr></w:lvl>");b.append("</w:abstractNum>");}return b+"<w:num w:numId=\"1\"><w:abstractNumId w:val=\"0\"/></w:num><w:num w:numId=\"2\"><w:abstractNumId w:val=\"1\"/></w:num>"+listOverrides+"</w:numbering>";}

 private String body(String raw)throws Exception {
  StringBuilder out=new StringBuilder();boolean titleSeen=false;int headingId=0;
  if(layout.blocks.isEmpty()||!layout.blocks.get(0).kind.equals("heading")||layout.blocks.get(0).level!=1){out.append(paragraph(layout.title,"Title",false,false,0));intro(out);titleSeen=true;}
  for(DocumentLayout.Block b:layout.blocks)switch(b.kind){
   case "heading":int id=++headingId;out.append("<w:p><w:pPr><w:pStyle w:val=\"").append(b.level==1?"Title":"Heading"+Math.min(3,b.level-1)).append("\"/></w:pPr><w:bookmarkStart w:id=\"").append(id).append("\" w:name=\"section").append(id).append("\"/>").append(inline(b.text)).append("<w:bookmarkEnd w:id=\"").append(id).append("\"/></w:p>");if(b.level==1&&!titleSeen){intro(out);titleSeen=true;}break;
   case "math":out.append("<w:p><w:pPr><w:jc w:val=\"center\"/><w:keepLines/><w:spacing w:before=\"150\" w:after=\"180\"/></w:pPr><m:oMathPara>").append(OfficeMath.xml(b.text)).append("</m:oMathPara></w:p>");break;
   case "table":out.append(table(b.rows,b.align));break;
   case "list":int number=1;if(b.ordered){number=++listId;listOverrides.append("<w:num w:numId=\"").append(number).append("\"><w:abstractNumId w:val=\"1\"/><w:lvlOverride w:ilvl=\"").append(b.level).append("\"><w:startOverride w:val=\"").append(b.start).append("\"/></w:lvlOverride></w:num>");}out.append("<w:p><w:pPr><w:numPr><w:ilvl w:val=\"").append(b.level).append("\"/><w:numId w:val=\"").append(number).append("\"/></w:numPr><w:spacing w:after=\"90\"/><w:keepLines/></w:pPr>").append(inline(b.text)).append("</w:p>");break;
   case "code":for(String line:b.text.split("\n",-1))out.append(paragraph(line,"",true,false,0));break;
   case "quote":out.append(paragraph(b.text,"",false,true,0));break;
   case "break":out.append("<w:p><w:r><w:br w:type=\"page\"/></w:r></w:p>");break;
   default:out.append(paragraph(b.text,"",false,false,0));
  }return out.toString();
 }
 private void intro(StringBuilder out)throws Exception {
  if(!layout.subtitle.isEmpty())out.append("<w:p><w:pPr><w:keepNext/><w:spacing w:after=\"300\"/></w:pPr><w:r><w:rPr><w:color w:val=\"697881\"/><w:sz w:val=\"23\"/></w:rPr><w:t>").append(ArtifactFiles.xml(layout.subtitle)).append("</w:t></w:r></w:p>");
  if(!layout.toc)return;int entries=0;for(DocumentLayout.Block b:layout.blocks)if(b.kind.equals("heading")&&b.level>1&&b.level<=3)entries++;if(entries==0)return;
  out.append(paragraph("目录","Heading2",false,false,0));int id=0;for(DocumentLayout.Block b:layout.blocks){if(!b.kind.equals("heading"))continue;id++;if(b.level<2||b.level>3)continue;out.append("<w:p><w:pPr><w:ind w:left=\"").append((b.level-2)*300).append("\"/><w:spacing w:after=\"100\"/></w:pPr><w:hyperlink w:anchor=\"section").append(id).append("\">").append(run(b.text,false,false,false,false)).append("</w:hyperlink></w:p>");}out.append("<w:p><w:r><w:br w:type=\"page\"/></w:r></w:p>");
 }
 private String bodyLegacy(String raw)throws Exception {StringBuilder b=new StringBuilder();String[] lines=raw.split("\n",-1);boolean code=false;for(int i=0;i<lines.length;i++){String line=lines[i],trim=line.trim();if(trim.startsWith("```")){code=!code;continue;}if(code){b.append(paragraph(line,"",true,false,0));continue;}if(trim.isEmpty())continue;
   if(trim.startsWith("$$")||trim.startsWith("\\[")){String close=trim.startsWith("$$")?"$$":"\\]";StringBuilder math=new StringBuilder(trim.substring(2));while(!math.toString().trim().endsWith(close)&&i+1<lines.length)math.append('\n').append(lines[++i]);String formula=math.toString().trim();if(!formula.endsWith(close))throw new IOException("独立公式没有闭合，请修正正文");formula=formula.substring(0,formula.length()-2);b.append("<w:p><w:pPr><w:jc w:val=\"center\"/><w:spacing w:before=\"130\" w:after=\"160\"/></w:pPr><m:oMathPara>").append(OfficeMath.xml(formula)).append("</m:oMathPara></w:p>");continue;}
   if(i+1<lines.length&&line.contains("|")&&lines[i+1].trim().matches("\\|?\\s*:?-{3,}:?\\s*(\\|\\s*:?-{3,}:?\\s*)+\\|?")){List<String[]> rows=new ArrayList<>();rows.add(ArtifactFiles.tableCells(line));i+=2;while(i<lines.length&&lines[i].contains("|")&&!lines[i].trim().isEmpty())rows.add(ArtifactFiles.tableCells(lines[i++]));i--;b.append(table(rows));continue;}
   Matcher h=Pattern.compile("^(#{1,6})\\s+(.*)$").matcher(line);if(h.matches()){int n=h.group(1).length();b.append(paragraph(h.group(2),n==1?"Title":"Heading"+Math.min(3,n-1),false,false,0));continue;}
   Matcher list=Pattern.compile("^(\\s*)([-*+]|\\d+[.)])\\s+(.*)$").matcher(line);if(list.matches()){int level=Math.min(3,list.group(1).length()/2),number=list.group(2).matches("\\d+.*")?2:1;b.append("<w:p><w:pPr><w:numPr><w:ilvl w:val=\"").append(level).append("\"/><w:numId w:val=\"").append(number).append("\"/></w:numPr><w:spacing w:after=\"90\"/></w:pPr>").append(inline(list.group(3))).append("</w:p>");continue;}
   if(trim.matches("[-*_]{3,}"))continue;b.append(paragraph(line.replaceFirst("^>\\s?",""),"",false,trim.startsWith(">"),0));
  }if(code)throw new IOException("代码围栏没有闭合，请修正正文");return b.toString();
 }
 private String paragraph(String line,String style,boolean code,boolean quote,int cell)throws Exception {StringBuilder b=new StringBuilder("<w:p><w:pPr>");if(!style.isEmpty())b.append("<w:pStyle w:val=\"").append(style).append("\"/>");if(code)b.append("<w:shd w:fill=\"F1F4F3\"/><w:spacing w:after=\"0\" w:line=\"270\"/>");if(quote)b.append("<w:ind w:left=\"360\"/><w:shd w:fill=\"F2F6F4\"/>");if(cell>0)b.append("<w:spacing w:after=\"50\" w:before=\"50\" w:line=\"280\"/>");b.append("</w:pPr>");if(code)b.append(run(line,false,false,true,false));else if(cell==2)b.append(run(line.replace("**",""),true,false,false,true));else b.append(inline(line));return b+"</w:p>";}

 private String inline(String raw)throws Exception {StringBuilder out=new StringBuilder();for(DocumentInline.Run r:DocumentInline.parse(raw)){String content=r.math?OfficeMath.xml(r.text):run(r.text,r.bold,r.italic,r.code,false);if(!r.link.isEmpty()){String id="link"+(++linkNumber);links.append("<Relationship Id=\"").append(id).append("\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink\" Target=\"").append(ArtifactFiles.xml(r.link)).append("\" TargetMode=\"External\"/>");content="<w:hyperlink r:id=\""+id+"\">"+content+"</w:hyperlink>";}out.append(content);}return out.toString();}
 private String run(String text,boolean bold,boolean italic,boolean code,boolean white){if(text.isEmpty())return "";return "<w:r><w:rPr>"+(bold?"<w:b/>":"")+(italic?"<w:i/>":"")+(white?"<w:color w:val=\"FFFFFF\"/><w:sz w:val=\"20\"/>":"")+(code?"<w:rFonts w:ascii=\"Consolas\" w:hAnsi=\"Consolas\"/><w:sz w:val=\"19\"/>":"")+"</w:rPr><w:t xml:space=\"preserve\">"+ArtifactFiles.xml(text).replace("\n","</w:t><w:br/><w:t xml:space=\"preserve\">")+"</w:t></w:r>";}
 private String table(List<String[]> rows)throws Exception {return table(rows,null);}
 private String table(List<String[]> rows,String[] align)throws Exception {int cols=rows.get(0).length;if(cols>8)throw new IOException("Word表格超过8列，请拆分或改用Excel");int width=(layout.landscape?16838:11906)-2880;int[] widths=DocumentLayout.widths(rows,width);StringBuilder b=new StringBuilder("<w:tbl><w:tblPr><w:tblW w:w=\""+width+"\" w:type=\"dxa\"/><w:tblLayout w:type=\"fixed\"/><w:tblBorders><w:bottom w:val=\"single\" w:sz=\"4\" w:color=\"DDE5E1\"/><w:insideH w:val=\"single\" w:sz=\"4\" w:color=\"DDE5E1\"/></w:tblBorders><w:tblCellMar><w:top w:w=\"105\" w:type=\"dxa\"/><w:left w:w=\"130\" w:type=\"dxa\"/><w:bottom w:w=\"105\" w:type=\"dxa\"/><w:right w:w=\"130\" w:type=\"dxa\"/></w:tblCellMar></w:tblPr><w:tblGrid>");for(int c=0;c<cols;c++)b.append("<w:gridCol w:w=\"").append(widths[c]).append("\"/>");b.append("</w:tblGrid>");for(int r=0;r<rows.size();r++){b.append("<w:tr><w:trPr>").append(r==0?"<w:tblHeader/>":"").append(shortRow(rows.get(r))?"<w:cantSplit/>":"").append("</w:trPr>");for(int c=0;c<cols;c++)b.append("<w:tc><w:tcPr><w:tcW w:w=\"").append(widths[c]).append("\" w:type=\"dxa\"/><w:vAlign w:val=\"center\"/><w:shd w:fill=\"").append(r==0?accent:r%2==0?"F3F6F5":"FFFFFF").append("\"/></w:tcPr>").append(cell(rows.get(r)[c],r==0,align==null?"left":align[c])).append("</w:tc>");b.append("</w:tr>");}return b.append("</w:tbl><w:p><w:pPr><w:spacing w:after=\"60\"/></w:pPr></w:p>").toString();}
 private boolean shortRow(String[] row){for(String text:row)if(text.length()>350)return false;return true;}
 private String cell(String text,boolean header,String align)throws Exception {String result=paragraph(text,"",false,false,header?2:1);return result.replace("<w:pPr>","<w:pPr><w:jc w:val=\""+align+"\"/>"+(header?"<w:keepNext/>":""));}

}
